(n, m) = (input(), input())
ln = len(n)
lm = len(m)
ans = cnt = 0
for i in range(lm):
	if n[i] == '1':
		cnt += 1
	if m[i] == '1':
		cnt += 1
if cnt % 2 == 0:
	ans = 1
for i in range(lm, ln):
	if n[i] == '1':
		cnt += 1
	if n[i - lm] == '1':
		cnt -= 1
	if cnt % 2 == 0:
		ans += 1
print(ans)
